import { Injectable } from "@nestjs/common";
import { SeverityLevel } from "@prisma/client";
import { DetectionMetricsPack } from "./risk-detection-metrics-collector.service";

export interface RuleSignal {
  signalCode: string;
  title: string;
  category: string;
  severity: SeverityLevel;
  probability: number;
  impact: number;
  evidence: Record<string, unknown>;
  ruleConfidence: number;
  descriptionDraft: string;
}

/** Deterministic signals only — no ML; aligns scoring bands with dashboard RAG thresholds. */
@Injectable()
export class RiskDetectionRulesService {
  evaluate(pack: DetectionMetricsPack): RuleSignal[] {
    const out: RuleSignal[] = [];
    const seen = new Set<string>();
    const push = (s: RuleSignal) => {
      if (seen.has(s.signalCode)) return;
      seen.add(s.signalCode);
      out.push(s);
    };

    if (pack.schedule) {
      if (pack.schedule.scheduleStatus === "RED") {
        push({
          signalCode: "SCHEDULE_VARIANCE_CRITICAL",
          title: "Schedule materially behind the baseline curve",
          category: "SCHEDULE",
          severity: "HIGH",
          probability: 0.62,
          impact: 0.74,
          evidence: {
            scheduleVariancePercent: pack.schedule.scheduleVariancePercent,
            scheduleStatus: pack.schedule.scheduleStatus,
            actualProgressPercent: pack.schedule.actualProgressPercent,
            expectedProgressPercent: pack.schedule.expectedProgressPercent,
          },
          ruleConfidence: 82,
          descriptionDraft: `Backend schedule variance is ${pack.schedule.scheduleVariancePercent}% (actual ${pack.schedule.actualProgressPercent}% vs expected ${pack.schedule.expectedProgressPercent}%) with status ${pack.schedule.scheduleStatus}.`,
        });
      } else if (pack.schedule.scheduleStatus === "AMBER") {
        push({
          signalCode: "SCHEDULE_VARIANCE_PRESSURE",
          title: "Schedule trending behind planned execution",
          category: "SCHEDULE",
          severity: "MEDIUM",
          probability: 0.48,
          impact: 0.58,
          evidence: {
            scheduleVariancePercent: pack.schedule.scheduleVariancePercent,
            scheduleStatus: pack.schedule.scheduleStatus,
          },
          ruleConfidence: 66,
          descriptionDraft: `Schedule variance ${pack.schedule.scheduleVariancePercent}% sits in the amber control band.`,
        });
      }
    }

    if (pack.financial && !("unavailableReason" in pack.financial && pack.financial.unavailableReason)) {
      const rag = pack.financial.ragStatus;
      if (rag === "RED") {
        push({
          signalCode: "COST_PERFORMANCE_CRITICAL",
          title: "Forecast cost performance in critical band versus approved budget",
          category: "COST",
          severity: "HIGH",
          probability: 0.58,
          impact: 0.72,
          evidence: {
            costVariancePercent: pack.financial.costVariancePercent,
            ragStatus: rag,
          },
          ruleConfidence: 80,
          descriptionDraft: `FinancialSummary CV% ${pack.financial.costVariancePercent ?? "n/a"} with cost RAG ${rag}.`,
        });
      } else if (rag === "AMBER") {
        push({
          signalCode: "COST_VARIANCE_WARNING",
          title: "Emerging budget pressure versus approved baseline",
          category: "COST",
          severity: "MEDIUM",
          probability: 0.42,
          impact: 0.52,
          evidence: { costVariancePercent: pack.financial.costVariancePercent, ragStatus: rag },
          ruleConfidence: 62,
          descriptionDraft: `CV% ${pack.financial.costVariancePercent ?? "n/a"} flagged amber by backend thresholds.`,
        });
      }
    }

    const stressed = pack.resourceStress.filter((r) => r.overAllocated);
    if (stressed.length) {
      const severe = stressed.some((r) => r.sumAllocationPercent >= r.thresholdPercent * 1.2);
      push({
        signalCode: "RESOURCE_CAPACITY_OVER_THRESHOLD",
        title: "Approved allocations exceed capacity governance thresholds",
        category: "RESOURCE",
        severity: severe ? "HIGH" : "MEDIUM",
        probability: severe ? 0.55 : 0.44,
        impact: severe ? 0.68 : 0.52,
        evidence: {
          resources: stressed.map((r) => ({
            resourceCode: r.resourceCode,
            sumAllocationPercent: r.sumAllocationPercent,
            thresholdPercent: r.thresholdPercent,
          })),
        },
        ruleConfidence: severe ? 76 : 63,
        descriptionDraft: `${stressed.length} resource(s) carry APPROVED allocations above configured thresholds.`,
      });
    }

    if (pack.dependencyLagCount >= 3) {
      push({
        signalCode: "DEPENDENCY_CHAIN_SLIPPAGE",
        title: "Multiple successor tasks remain incomplete beyond planned finish",
        category: "DEPENDENCY",
        severity: "MEDIUM",
        probability: 0.46,
        impact: 0.54,
        evidence: { dependencyLagCount: pack.dependencyLagCount },
        ruleConfidence: 64,
        descriptionDraft: `${pack.dependencyLagCount} successor tasks are behind planned completion while incomplete.`,
      });
    }

    if (pack.openRiskSeverityCounts.critical >= 2) {
      push({
        signalCode: "CRITICAL_RISK_BACKLOG",
        title: "Elevated open CRITICAL risks on the same scope",
        category: "RIC_HISTORY",
        severity: "HIGH",
        probability: 0.52,
        impact: 0.7,
        evidence: { openCriticalRisks: pack.openRiskSeverityCounts.critical },
        ruleConfidence: 74,
        descriptionDraft: `${pack.openRiskSeverityCounts.critical} CRITICAL risks remain open for this scope.`,
      });
    }

    if (pack.escalatedOpenIssues >= 2) {
      push({
        signalCode: "ISSUE_ESCALATION_LOAD",
        title: "Multiple escalated issues remain open",
        category: "RIC_HISTORY",
        severity: "MEDIUM",
        probability: 0.44,
        impact: 0.5,
        evidence: { escalatedOpenIssues: pack.escalatedOpenIssues },
        ruleConfidence: 61,
        descriptionDraft: `${pack.escalatedOpenIssues} issues are escalated and still open.`,
      });
    }

    if (pack.programProjectScheduleBands) {
      const reds = pack.programProjectScheduleBands.filter((p) => p.scheduleStatus === "RED");
      if (reds.length >= 2) {
        push({
          signalCode: "PROGRAM_SCHEDULE_DIVERGENCE",
          title: "Program showing coordinated schedule stress across member projects",
          category: "PROGRAM",
          severity: "HIGH",
          probability: 0.54,
          impact: 0.66,
          evidence: {
            redProjectCodes: reds.map((r) => r.code),
          },
          ruleConfidence: 72,
          descriptionDraft: `${reds.length} projects under the program report RED schedule bands concurrently.`,
        });
      }
    }

    return out;
  }
}

import { createHash } from "crypto";
import { Injectable, Logger } from "@nestjs/common";
import { RuleSignal } from "./risk-detection-rules.service";

export interface AiEnrichmentResult {
  mitigationDraft: string;
  aiExplanationJson: Record<string, unknown>;
}

/** Open-source local summarization for mitigation drafts only — metrics remain untouched. */
@Injectable()
export class RiskDetectionAiService {
  private readonly logger = new Logger(RiskDetectionAiService.name);
  private summarizer: ((text: string, opts?: Record<string, unknown>) => Promise<unknown>) | null = null;

  private async getSummarizer(modelId: string) {
    if (this.summarizer) return this.summarizer;
    const { pipeline } = await import("@xenova/transformers");
    this.summarizer = (await pipeline("summarization", modelId)) as (
      text: string,
      opts?: Record<string, unknown>,
    ) => Promise<unknown>;
    return this.summarizer;
  }

  private templateMitigation(signal: RuleSignal): string {
    return [
      `Governance controls: route ${signal.signalCode} through the PMO risk forum; validate assumptions with owners.`,
      `Establish corrective checkpoints within one steering cycle; tie milestones to dependency recovery where applicable.`,
      `Document variance drivers referenced in evidence JSON before mobilizing budget or schedule contingency.`,
    ].join(" ");
  }

  async enrichMitigation(signal: RuleSignal, metricsFactsDigest: string): Promise<AiEnrichmentResult> {
    const modelId = process.env.RISK_DETECTION_AI_MODEL ?? "Xenova/distilbart-cnn-6-6";
    const inputBullets = [
      `Signal ${signal.signalCode} (${signal.category}) severity ${signal.severity}.`,
      signal.descriptionDraft,
      `Evidence keys: ${JSON.stringify(signal.evidence).slice(0, 1200)}`,
      "Draft mitigation and controls text only; do not invent metrics.",
    ].join("\n");

    const inputHash = createHash("sha256").update(metricsFactsDigest + signal.signalCode).digest("hex");
    let fallbackUsed = false;
    let mitigationDraft = "";

    try {
      const summarizer = await this.getSummarizer(modelId);
      const raw = await summarizer(inputBullets.slice(0, 2600), { max_length: 140, min_length: 36 });
      const row = Array.isArray(raw) ? raw[0] : raw;
      mitigationDraft =
        typeof row === "object" && row !== null && "summary_text" in row ? String((row as { summary_text: string }).summary_text) : "";
      if (!mitigationDraft.trim()) throw new Error("empty summarizer output");
    } catch (e) {
      fallbackUsed = true;
      this.logger.warn(`Mitigation AI fallback: ${(e as Error).message}`);
      mitigationDraft = this.templateMitigation(signal);
    }

    return {
      mitigationDraft,
      aiExplanationJson: {
        modelId,
        fallbackUsed,
        inputFactsDigest: metricsFactsDigest,
        signalCode: signal.signalCode,
        inputHash,
        inputPreview: inputBullets.slice(0, 400),
      },
    };
  }

  aiConfidenceAdjustment(fallbackUsed: boolean): number {
    return fallbackUsed ? 0 : 6;
  }
}

import {
  BadRequestException,
  ConflictException,
  ForbiddenException,
  Injectable,
  NotFoundException,
} from "@nestjs/common";
import {
  DetectedRiskSuggestionStatus,
  FinancialObjectType,
  Prisma,
  SeverityLevel,
} from "@prisma/client";
import { createHash } from "crypto";
import { RequestUser } from "../common/auth/request-user.interface";
import { PrismaService } from "../prisma/prisma.service";
import { WorkflowIntegrationFacade } from "../workflow/workflow.integration";
import { AuditService } from "../workflow/audit.service";
import { DismissDetectedRiskSuggestionDto } from "./dto/dismiss-detected-risk.dto";
import { RunRiskDetectionDto } from "./dto/run-risk-detection.dto";
import { SubmitDetectedRiskSuggestionDto } from "./dto/submit-detected-risk.dto";
import { RiskDetectionAiService } from "./risk-detection-ai.service";
import { DetectionMetricsPack, RiskDetectionMetricsCollectorService } from "./risk-detection-metrics-collector.service";
import { RiskDetectionRulesService } from "./risk-detection-rules.service";

@Injectable()
export class RiskDetectionService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly auditService: AuditService,
    private readonly workflowIntegration: WorkflowIntegrationFacade,
    private readonly collector: RiskDetectionMetricsCollectorService,
    private readonly rules: RiskDetectionRulesService,
    private readonly ai: RiskDetectionAiService,
  ) {}

  async runAnalysis(dto: RunRiskDetectionDto, actor: RequestUser) {
    this.assertTenant(dto.tenantId, actor);
    const refreshMetrics = dto.refreshMetrics ?? false;
    const proposedOwnerId = dto.proposedOwnerId ?? actor.userId;

    const metrics = await this.collector.collect(
      dto.tenantId,
      dto.scopeType,
      dto.scopeId,
      dto.periodLabel,
      actor,
      refreshMetrics,
    );

    const metricsFactsDigest = createHash("sha256").update(JSON.stringify(metrics)).digest("hex");

    const signals = this.rules.evaluate(metrics);
    const run = await this.prisma.riskDetectionRun.create({
      data: {
        tenantId: dto.tenantId,
        scopeType: dto.scopeType,
        scopeId: dto.scopeId,
        periodLabel: dto.periodLabel,
        metricsSnapshot: this.json(metrics),
        factsDigest: metricsFactsDigest,
        createdBy: actor.userId,
      },
    });

    const suggestions: unknown[] = [];
    for (const signal of signals) {
      const { mitigationDraft, aiExplanationJson } = await this.ai.enrichMitigation(signal, metricsFactsDigest);
      const aiAdj = this.ai.aiConfidenceAdjustment(Boolean(aiExplanationJson.fallbackUsed));
      const confidenceScore = Math.min(100, signal.ruleConfidence + aiAdj);

      const severityWeight = this.ricSeverityWeight(signal.severity);
      const exposureScore = Number((signal.probability * signal.impact * severityWeight).toFixed(4));

      const row = await this.prisma.detectedRiskSuggestion.create({
        data: {
          runId: run.id,
          tenantId: dto.tenantId,
          objectType: dto.scopeType,
          objectId: dto.scopeId,
          signalCode: signal.signalCode,
          title: signal.title,
          descriptionDraft: signal.descriptionDraft,
          category: signal.category,
          probability: new Prisma.Decimal(signal.probability),
          impact: new Prisma.Decimal(signal.impact),
          severity: signal.severity,
          severityWeight: new Prisma.Decimal(severityWeight),
          exposureScore: new Prisma.Decimal(exposureScore),
          confidenceScore: new Prisma.Decimal(confidenceScore),
          mitigationDraft,
          evidenceJson: this.json(signal.evidence),
          aiExplanationJson: this.json(aiExplanationJson),
          proposedOwnerId,
          status: DetectedRiskSuggestionStatus.PROPOSED,
        },
      });
      suggestions.push(row);
    }

    await this.auditService.log({
      tenantId: dto.tenantId,
      entityType: "RiskDetectionRun",
      entityId: run.id,
      action: "RISK_DETECTION_RUN_CREATED",
      actorId: actor.userId,
      newValue: {
        factsDigest: metricsFactsDigest,
        suggestionCount: signals.length,
        scopeType: dto.scopeType,
        scopeId: dto.scopeId,
      },
    });

    return { run, suggestions };
  }

  async listRuns(tenantId: string, actor: RequestUser) {
    this.assertTenant(tenantId, actor);
    return this.prisma.riskDetectionRun.findMany({
      where: { tenantId },
      orderBy: { createdAt: "desc" },
      take: 50,
      include: { suggestions: { select: { id: true, signalCode: true, status: true, title: true } } },
    });
  }

  async getRun(runId: string, tenantId: string, actor: RequestUser) {
    this.assertTenant(tenantId, actor);
    const run = await this.prisma.riskDetectionRun.findFirst({
      where: { id: runId, tenantId },
      include: { suggestions: { orderBy: { createdAt: "asc" } } },
    });
    if (!run) throw new NotFoundException("Risk detection run not found.");
    return run;
  }

  async listSuggestions(
    tenantId: string,
    actor: RequestUser,
    status?: DetectedRiskSuggestionStatus,
    runId?: string,
  ) {
    this.assertTenant(tenantId, actor);
    return this.prisma.detectedRiskSuggestion.findMany({
      where: {
        tenantId,
        ...(status ? { status } : {}),
        ...(runId ? { runId } : {}),
      },
      orderBy: { createdAt: "desc" },
      take: 200,
      include: { run: { select: { id: true, periodLabel: true, scopeType: true, scopeId: true, factsDigest: true } } },
    });
  }

  async getSuggestion(suggestionId: string, tenantId: string, actor: RequestUser) {
    this.assertTenant(tenantId, actor);
    const s = await this.prisma.detectedRiskSuggestion.findFirst({
      where: { id: suggestionId, tenantId },
      include: { run: true },
    });
    if (!s) throw new NotFoundException("Suggestion not found.");
    return s;
  }

  async submitForApproval(suggestionId: string, dto: SubmitDetectedRiskSuggestionDto, actor: RequestUser) {
    this.assertTenant(dto.tenantId, actor);
    const suggestion = await this.prisma.detectedRiskSuggestion.findFirst({
      where: { id: suggestionId, tenantId: dto.tenantId },
    });
    if (!suggestion) throw new NotFoundException("Suggestion not found.");
    if (suggestion.status !== DetectedRiskSuggestionStatus.PROPOSED) {
      throw new ConflictException("Only PROPOSED suggestions can enter workflow approval.");
    }
    if (suggestion.workflowInstanceId) {
      throw new ConflictException("Workflow already linked.");
    }

    const wf = await this.workflowIntegration.forRiskDetection().startDetectedRiskSuggestionApproval(dto.tenantId, suggestionId, actor);

    const updated = await this.prisma.detectedRiskSuggestion.update({
      where: { id: suggestionId },
      data: {
        status: DetectedRiskSuggestionStatus.UNDER_REVIEW,
        workflowInstanceId: wf.id,
      },
    });

    await this.auditService.log({
      tenantId: dto.tenantId,
      entityType: "DetectedRiskSuggestion",
      entityId: suggestionId,
      action: "DETECTED_RISK_SUBMITTED_FOR_APPROVAL",
      actorId: actor.userId,
      newValue: { workflowInstanceId: wf.id, signalCode: suggestion.signalCode },
    });

    return { suggestion: updated, workflowInstance: wf };
  }

  async dismiss(suggestionId: string, dto: DismissDetectedRiskSuggestionDto, actor: RequestUser) {
    this.assertTenant(dto.tenantId, actor);
    const suggestion = await this.prisma.detectedRiskSuggestion.findFirst({
      where: { id: suggestionId, tenantId: dto.tenantId },
    });
    if (!suggestion) throw new NotFoundException("Suggestion not found.");
    if (suggestion.status !== DetectedRiskSuggestionStatus.PROPOSED) {
      throw new ConflictException("Only PROPOSED suggestions can be dismissed without workflow.");
    }

    const updated = await this.prisma.detectedRiskSuggestion.update({
      where: { id: suggestionId },
      data: {
        status: DetectedRiskSuggestionStatus.DISMISSED,
        reviewerNotes: dto.reason ?? null,
      },
    });

    await this.auditService.log({
      tenantId: dto.tenantId,
      entityType: "DetectedRiskSuggestion",
      entityId: suggestionId,
      action: "DETECTED_RISK_DISMISSED",
      actorId: actor.userId,
      oldValue: { status: suggestion.status, signalCode: suggestion.signalCode },
      newValue: { status: updated.status, reason: dto.reason ?? null },
    });

    return updated;
  }

  private ricSeverityWeight(severity: SeverityLevel): number {
    if (severity === "CRITICAL") return 10;
    if (severity === "HIGH") return 6;
    if (severity === "MEDIUM") return 3;
    return 1;
  }

  private json(value: unknown): Prisma.InputJsonValue {
    return JSON.parse(JSON.stringify(value)) as Prisma.InputJsonValue;
  }

  private assertTenant(tenantId: string, actor: RequestUser) {
    if (tenantId !== actor.tenantId) throw new ForbiddenException("Cross-tenant access denied.");
  }
}

import { Body, Controller, Get, Param, Post, Query, UseGuards } from "@nestjs/common";
import { DetectedRiskSuggestionStatus } from "@prisma/client";
import { Actor } from "../common/auth/actor.decorator";
import { AuthGuard } from "../common/auth/auth.guard";
import { RequestUser } from "../common/auth/request-user.interface";
import { Permissions } from "../common/rbac/permissions.decorator";
import { RbacGuard } from "../common/rbac/rbac.guard";
